import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { updateLineItemInCartWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await updateLineItemInCartWorkflow(req.scope)
    .run({
      input: {
        cart_id: "cart_123",
        item_id: "item_123",
        update: {
          quantity: 2
        }
      }
    })

  res.send(result)
}

